with home as (select id from public.site_pages where slug = 'home' limit 1),
base as (select coalesce(max(s.sort_order), 0) as m from public.page_sections s, home where s.page_id = home.id)
insert into public.page_sections (page_id, section_type, eyebrow, title, body, cta_label, cta_url, config, is_visible, sort_order)
select home.id, v.t, v.e, v.ti, v.b, v.cl, v.cu, v.c::jsonb, true, base.m + v.o from home, base, (values
 ('services_snapshot','WHAT WE DO', E'Everything You Need\nto Create, Build and Grow.', 'Creative, AI and technology services brought together under one team.', 'All services', '/services',
  '{"items":[{"label":"AI Commercial","description":"TVC, OVC, product films, motion and branded video.","slug":"ai-commercial","enabled":true},{"label":"AI Content & Creative","description":"Social content, UGC-style visuals and campaign creative.","slug":"ai-content-creative","enabled":true},{"label":"AI Photography","description":"Product, fashion and lifestyle imagery made with AI.","slug":"ai-photography","enabled":true},{"label":"Brand & Design","description":"Identity, visual systems and design for every touchpoint.","slug":"brand-design","enabled":true},{"label":"Web & Software","description":"Websites, platforms and digital products built to scale.","slug":"web-software","enabled":true},{"label":"AI Automation","description":"Workflows and AI tools that save your team time.","slug":"ai-automation","enabled":true}]}', 10),
 ('pricing','WORK WITH BRANTA', E'A Simple Way to\nStart Working Together.', 'Choose the level of support that fits what you''re trying to create or build.', null, null,
  '{"plans":[{"id":"starter","name":"Starter","tagline":"For focused creative needs.","price_type":"custom","price":"","price_max":"","currency":"","features":["Defined project scope","Creative direction","Production","Revision rounds","Final delivery"],"cta_label":"Get a Quote","cta_url":"/start-a-project","highlighted":false,"badge":"","enabled":true},{"id":"growth","name":"Growth","tagline":"For brands that need ongoing creative support.","price_type":"custom","price":"","price_max":"","currency":"","features":["Multiple deliverables","AI content / commercial work","Campaign creative","Priority production","Regular revisions","Ongoing support"],"cta_label":"Talk to Us","cta_url":"/book-a-call","highlighted":true,"badge":"MOST POPULAR","enabled":true},{"id":"custom","name":"Custom","tagline":"For larger creative, software or automation projects.","price_type":"custom","price":"","price_max":"","currency":"","features":["Web & Software","AI Automation","Large campaigns","Custom workflows","Dedicated planning","Tailored scope"],"cta_label":"Book a Call","cta_url":"/book-a-call","highlighted":false,"badge":"","enabled":true}]}', 20),
 ('book_call_cta','HAVE A PROJECT IN MIND?', E'Let''s Talk About\nWhat You''re Building.', 'Tell us what you need and let''s find the right direction together.', 'Book a Call', '/book-a-call',
  '{"secondary_cta_label":"Start a Project","secondary_cta_url":"/start-a-project"}', 30)
) as v(t,e,ti,b,cl,cu,c,o);